<?php

namespace App\Modules\Lead\Http\Policies;

use App\Models\User;
use App\Modules\Lead\Domain\Models\Lead;

/**
 * Per-instance authorization for a single already-resolved Lead - listing
 * scope lives in LeadFilter instead. Admin is granted both methods here
 * implicitly via CorePermissionsServiceProvider's `Gate::before`; a
 * Commercial sees/acts only on leads assigned to them, whether assigned
 * by an Admin, imported by them, or generated by their own properties.
 */
class LeadPolicy
{
    public function view(User $user, Lead $lead): bool
    {
        return $lead->commercial_id !== null && $user->id === $lead->commercial_id;
    }

    public function updateStatus(User $user, Lead $lead): bool
    {
        return $lead->commercial_id !== null && $user->id === $lead->commercial_id;
    }

    public function manageContact(User $user, Lead $lead): bool
    {
        return $lead->commercial_id !== null && $user->id === $lead->commercial_id;
    }
}
